<template>
  <div class="view">
    <div class="state-window block">
     
      <div :class="`state-window-content waiting total-${variants}`">
          <div class="variant" v-for="i in variants" :key="i">
            <div class="plane" ref="plane"></div>
            <div :class="`kvalue k-${rules[ruleSelected].color}`" ref="kvalue">
              <span>{{ parseFloat(reactive[i-1]).toFixed(2) }} x</span>
            </div>
          </div>
      </div>
      <div class="info-shape shape-tutorial" @click="$router.push('/tutorial')">
        <img src="@/assets/info.svg" alt="">
      </div>
    </div>
    <div class="block flex">
      <span class="heading">The rate is {{rules[ruleSelected].bank}} of your bank</span>
      <p>{{ rules[ruleSelected].description }}</p>
      
      <div class="action-table">
        <input type="checkbox" v-bind:disabled="step == 'flying'" id="double" @input="setDouble">
        <div class="toggle-btn">
          <span>Double rate</span>
          <label for="double" class="toggle"></label>
        </div>
        <div class="shape-timer">
          {{timer}} sec
        </div>
      </div>
     
      <button class="btn btn-primary" v-bind:disabled="step == 'flying'" @click="forecast()"><img src="@/assets/green-btn.svg" alt="">Forecast</button>
    </div>
    <div class="variants">
      <div :class="`rule r-${rule.color} ${(rule.id == ruleSelected) ? 'selected' : ''}`" v-for="rule in rules" @click="selectRule(rule.id)" :key="rule">
        <div :class="`badge ${rule.color}`">
          <img src="@/assets/btn-shadown.svg" class="shadow" alt="">
          <img src="@/assets/shield.svg" class="btn-icon" v-if="rule.icon == 'shield'" alt="icon">
          <img src="@/assets/average.svg" class="btn-icon" v-if="rule.icon == 'average'" alt="icon">
          <img src="@/assets/high_risk.svg" class="btn-icon" v-if="rule.icon == 'high_risk'" alt="icon">
          {{ rule.name }}
        </div>
        <span>{{ parseFloat(rule.start).toFixed(2)}}X - {{ parseFloat(rule.stop).toFixed(2)}}X</span>
      </div>
    </div>
  </div>
</template>

<script>
// @ is an alias to /src


export default {
  name: 'HomeView',
  data(){
    return {
      timer : 25,
      variants: 1,
      interval : null,
      coefs : [1.32,1.54],
      reactive : [0,0],
      ruleSelected : 0,
      rules : [
        {
          id : 0,
          name : '61.11% WIN',
          start: 1.00,
          stop: 2.00,
          description : "This strategy allows you to get stable, albeit small winnings, minimizing the risk of loss.",
          color: 'green',
          icon : 'shield',
          bank : '3-5%'
        },
        {
          id : 1,
          name : '16.67% WIN',
          start: 2,
          stop: 10,
          description : "Statistics show that these odds fall out about 40% of the time, making this strategy a balanced strategy between risk and reward.",
          color: 'orange',
          icon : 'average',
          bank : '2-5%'
        },
        {
          id : 2,
          name : '22.22% WIN',
          start: 10,
          stop: 1000,
          description : "Such high odds are rare, about once every 1-1.5 hours. This strategy is suitable for patient players who are ready to take high risks for a big win.",
          color: 'red',
          icon : 'high_risk',
          bank : '1% or <'
        }
      ],
      step : "waiting"
    }
  },
  components: {
    
  },
  methods : {
    setDouble(ev){
      if(ev.target.checked) this.variants = 2;
      else this.variants = 1;
      
    },
    selectRule(id){
      this.ruleSelected = id;
    },
    calculateSpeed(targetCoefficient, totalTime) {
     
     
      const step = 0.01;
      const stepsNeeded = targetCoefficient / step;

      const speed = stepsNeeded / totalTime;

      return speed;
    },
    forecast(){
      


      
      let rule = this.rules[this.ruleSelected];
      let min = rule.start, max = rule.stop;
      let k1 = parseFloat(Math.random() * (max - min) + min).toFixed(2);
      let k2 = parseFloat(Math.random() * (max - min) + min).toFixed(2);


      const interVal1 = (1 / this.calculateSpeed(k1,22)) * 1000; // Время между шагами
      const interVal2 = (1 / this.calculateSpeed(k2,22)) * 1000; // Время между шагами
      let reactiveInterval1 = setInterval(() => {
        this.reactive[0] += 0.01;
        if(parseFloat(this.reactive[0]).toFixed(2) >= k1){
          clearInterval(reactiveInterval1)
          this.$refs.kvalue[0]?.classList.add('stop')
        }
      }, interVal1);
      let reactiveInterval2 = setInterval(() => {
        this.reactive[1] += 0.01;
        if(parseFloat(this.reactive[1]) >= k2){
          clearInterval(reactiveInterval2)
          this.$refs.kvalue[1]?.classList.add('stop')
        }
      }, interVal2);
      this.coefs = [k1,k2];
      this.step = 'flying'
      this.interval = setInterval(() => {
        this.timer--;
        if(this.timer == 0){
          clearInterval(this.interval);
          this.$refs.kvalue[1]?.classList.remove('stop')
          this.$refs.kvalue[0].classList.remove('stop')
          this.step = 'waiting';
          this.timer = 25;
          this.reactive = [0,0]
          
        }
      }, 1000);
      let planes = this.$refs.plane;
      
      for(let plane of planes){
        plane.style.transition = "5s ease-in-out 0s";
        plane.style.transform = "rotate(0deg)";

        setTimeout(() => {
          plane.style.bottom = '45%'
          plane.style.left = '55%'
          plane.style.transform = 'rotate(0deg)'
          setTimeout(() => {
            plane.style.transition = '.8s linear 0s';

            let effectInterval = setInterval(() => {
              if(this.timer > 3){
                plane.style.transform = `rotate(${0 - Math.floor(Math.random() * 4)}deg)`;
                let percent = Math.floor(Math.random() * 2);
                plane.style.left = `${Number(plane.style.left.split('%')[0]) + percent}%`;
                plane.style.bottom = `${Number(plane.style.bottom.split('%')[0]) + percent}%`;
                setTimeout(() => {
                  plane.style.transform = `rotate(0deg)`;
                  plane.style.bottom = '45%'
                  plane.style.left = '55%'
                }, 300);
              }
              else{
                clearInterval(effectInterval);
                plane.style.transition = '0.2s ease-in-out 0s'
                setTimeout(() => {
                  plane.style.transform = 'rotate(0deg)'
                  plane.style.bottom = '100%'
                  plane.style.left = '90%'; 
                }, 100);
                let counterInterval = setInterval(() => {
                  if(this.step == 'waiting'){
                    plane.style.transition = 'none';
                    setTimeout(() => {
                      plane.style.left = '-20px';
                      plane.style.bottom = '-20px';
                      plane.style.transform = 'rotate(10deg)'  
                      plane.style.transition = 'rotate(10deg)'  
                      setTimeout(() => {
                        plane.removeAttribute('style')
                      }, 100);
                    }, 10);
                    clearInterval(counterInterval);
                  }
                }, 200);
              }
            }, 400);
          }, 5000);
        }, 800);
      
      }
    }
  }
}
</script>
